WHENEVER SQLERROR EXIT SQL.SQLCODE
SET DEFINE OFF
BEGIN
 EXECUTE IMMEDIATE 'CREATE TABLE DAC_QUERY_CATALOG (QUERY_ID VARCHAR2(80) PRIMARY KEY,DATABASE_NAME VARCHAR2(80) NOT NULL,NAME VARCHAR2(200) NOT NULL,DESCRIPTION VARCHAR2(1000) NOT NULL,QUERY_VERSION NUMBER(10) DEFAULT 1 NOT NULL,SQL_TEXT CLOB NOT NULL,DEFAULT_BODY CLOB NOT NULL,BINDINGS_JSON CLOB NOT NULL,ENABLED NUMBER(1) DEFAULT 1 NOT NULL)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/
MERGE INTO DAC_QUERY_CATALOG t USING (SELECT 'EDS_BY_LOT' QUERY_ID FROM dual) s ON (t.QUERY_ID=s.QUERY_ID) WHEN NOT MATCHED THEN INSERT (QUERY_ID,DATABASE_NAME,NAME,DESCRIPTION,SQL_TEXT,DEFAULT_BODY,BINDINGS_JSON) VALUES(q'[EDS_BY_LOT]',q'[oracle]',q'[EDS 검사 조회]',q'[Lot별 검사 데이터와 최소 수율 조건으로 조회합니다.]',q'[SELECT LOT_ID,WAFER_ID,PRODUCT,TESTED_DIES,GOOD_DIES,YIELD_PCT,INSPECTED_AT FROM DAC_EDS_DATA WHERE (:lot_id IS NULL OR LOT_ID=:lot_id) AND (:min_yield IS NULL OR YIELD_PCT>=:min_yield) ORDER BY LOT_ID,WAFER_ID FETCH FIRST :limit ROWS ONLY]',q'[{"database_name": "oracle", "query_id": "EDS_BY_LOT", "lot_id": "LOT-101", "min_yield": 90, "limit": 100}]',q'[[{"name": "lot_id", "type": "string", "nullable": true, "maxLength": 40}, {"name": "limit", "type": "integer", "min": 1, "max": 1000}, {"name": "min_yield", "type": "number", "nullable": true, "min": 0, "max": 100}]]');
MERGE INTO DAC_QUERY_CATALOG t USING (SELECT 'DEFECT_BY_LOT' QUERY_ID FROM dual) s ON (t.QUERY_ID=s.QUERY_ID) WHEN NOT MATCHED THEN INSERT (QUERY_ID,DATABASE_NAME,NAME,DESCRIPTION,SQL_TEXT,DEFAULT_BODY,BINDINGS_JSON) VALUES(q'[DEFECT_BY_LOT]',q'[oracle]',q'[결함 조회]',q'[Lot과 심각도로 결함 이력을 조회합니다.]',q'[SELECT DEFECT_ID,LOT_ID,WAFER_ID,DEFECT_TYPE,SEVERITY,DEFECT_COUNT FROM DAC_DEFECT_DATA WHERE (:lot_id IS NULL OR LOT_ID=:lot_id) AND (:severity IS NULL OR SEVERITY=:severity) ORDER BY LOT_ID,WAFER_ID,DEFECT_ID FETCH FIRST :limit ROWS ONLY]',q'[{"database_name": "oracle", "query_id": "DEFECT_BY_LOT", "lot_id": "LOT-101", "severity": null, "limit": 100}]',q'[[{"name": "lot_id", "type": "string", "nullable": true, "maxLength": 40}, {"name": "limit", "type": "integer", "min": 1, "max": 1000}, {"name": "severity", "type": "string", "nullable": true, "maxLength": 20}]]');
MERGE INTO DAC_QUERY_CATALOG t USING (SELECT 'LOT_YIELD_SUMMARY' QUERY_ID FROM dual) s ON (t.QUERY_ID=s.QUERY_ID) WHEN NOT MATCHED THEN INSERT (QUERY_ID,DATABASE_NAME,NAME,DESCRIPTION,SQL_TEXT,DEFAULT_BODY,BINDINGS_JSON) VALUES(q'[LOT_YIELD_SUMMARY]',q'[oracle]',q'[Lot별 수율 요약]',q'[Lot별 웨이퍼 수와 평균 수율을 집계합니다.]',q'[SELECT LOT_ID,PRODUCT,COUNT(*) WAFER_COUNT,ROUND(AVG(YIELD_PCT),2) AVG_YIELD_PCT FROM DAC_EDS_DATA WHERE (:lot_id IS NULL OR LOT_ID=:lot_id) GROUP BY LOT_ID,PRODUCT ORDER BY LOT_ID,PRODUCT FETCH FIRST :limit ROWS ONLY]',q'[{"database_name": "oracle", "query_id": "LOT_YIELD_SUMMARY", "lot_id": null, "limit": 100}]',q'[[{"name": "lot_id", "type": "string", "nullable": true, "maxLength": 40}, {"name": "limit", "type": "integer", "min": 1, "max": 1000}]]');
COMMIT;
EXIT;
